WU_C = {6: 'S'}   # повороты корпуса — «спина» (номер в WU_N)

def _wu_apply():
    base = len(N['ru'])
    for j, row_ in enumerate(WU_N):
        for li, l in enumerate(LANGS):
            N[l].append(row_[li])
    arrs = {'uk': HUK, 'en': HEN, 'es': HES, 'de': HDE, 'pt': HPT, 'fr': HFR, 'pl': HPL, 'it': HIT, 'he': HHE, 'ja': HJA, 'ko': HKO}
    for j, (how, easy) in enumerate(WU_H):
        H[base + j] = (how[0], easy[0])
        for k in (how, easy):   # тот же порядок, в каком gen_wo.py собирает уникальные строки HU
            if k[0]:
                for li, l in enumerate(LANGS[1:], 1): arrs[l].append(k[li])
        if j in WU_C: C[base + j] = WU_C[j]
    return base

