    SPEC = {   # подводящие под тему дня (из прежних разминок)
        'Сила: спина, плечи, руки': [['Скольжение руками по стене вверх («ангел у стены»)', '45 с'], ['Отжимания от стены без паузы, медленно', '45 с']],
        'Сила: грудь, спина, плечи': [['Скольжение руками по стене вверх («ангел у стены»)', '45 с'], ['Отжимания от стены без паузы, медленно', '45 с']],
        'Сила: ноги и ягодицы': [['Мост на коврике', '45 с'], ['Полуприседы к стулу', '45 с']],
        'Сила: всё тело': [['Полуприседы к стулу', '45 с'], ['Отжимания от стены без паузы, медленно', '45 с']],
    }
    for w in W:
        p0 = w['parts'][0]
        if p0['k'] != 'warm' or w['id'] == '№13': continue
        if w['title'] in SPEC: spec = SPEC[w['title']]
        else: spec = [[p0['items'][-1][0], p0['items'][-1][1] or '2 мин']]   # HIIT / кардио: своё пробное ускорение в конце (у кардио без дозы — 2 мин)
        step = 'Ходьба на месте с махами рук' if w['track'] == 'm' else 'Шаг на месте с махами рук'
        items = common(step) + spec
        import re as _re
        def _sec(d):
            m = _re.search(r'(\d+)\s*мин', d); t = 60 * int(m.group(1)) if m else 0
            m = _re.search(r'(\d+)\s*с\b', d); t += int(m.group(1)) if m else 0
            return t * (2 if 'на каждую' in d else 1)
        sec = sum(_sec(d) for _, d in items)
        old = p0['m']; p0['items'] = items; p0['m'] = round(sec / 60)
        w['min'] += p0['m'] - old
